# Map : chaque ligne -> paires (mot, 1)
def map(ligne):
    for mot in ligne.split():
        emit(mot, 1)

# Reduce : somme des valeurs de chaque clé
def reduce(mot, valeurs):
    emit(mot, sum(valeurs))

CREATE EXTERNAL TABLE ventes_ext (produit STRING, montant DOUBLE)
ROW FORMAT DELIMITED FIELDS TERMINATED BY ','
LOCATION '/projet/ventes/';

SELECT produit, SUM(montant) AS total
FROM ventes
GROUP BY produit;

CREATE TABLE ventes (produit STRING, montant DOUBLE)
PARTITIONED BY (annee INT, mois INT);

SELECT produit, SUM(montant) FROM ventes
WHERE annee = 2024 AND mois = 5
GROUP BY produit;

